import{_ as s,o as t,c as e,ag as i}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"科学日报 · 2026-11-02（物理 · 体积散射显微 / Floquet 手性非线性光学）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/physics/science-daily-2026-11-02-physics.md","filePath":"topics/physics/science-daily-2026-11-02-physics.md"}'),n={name:"topics/physics/science-daily-2026-11-02-physics.md"};function r(c,o,l,a,d,g){return t(),e("div",null,[...o[0]||(o[0]=[i('<h1 id="科学日报-·-2026-11-02-物理-·-体积散射显微-floquet-手性非线性光学" tabindex="-1">科学日报 · 2026-11-02（物理 · 体积散射显微 / Floquet 手性非线性光学） <a class="header-anchor" href="#科学日报-·-2026-11-02-物理-·-体积散射显微-floquet-手性非线性光学" aria-label="Permalink to &quot;科学日报 · 2026-11-02（物理 · 体积散射显微 / Floquet 手性非线性光学）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-02.md</code> — 第52期 ｜ 科学板块（2 篇） 落盘说明：文件名带 <code>-physics</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-11-02-物理-·-1-2-体积散射显微-vsm——不扫描、不测波前-也能在强散射组织里重建三维荧光" tabindex="-1">科学日报 2026-11-02（物理 · 1/2）：体积散射显微 VSM——不扫描、不测波前，也能在强散射组织里重建三维荧光 <a class="header-anchor" href="#科学日报-2026-11-02-物理-·-1-2-体积散射显微-vsm——不扫描、不测波前-也能在强散射组织里重建三维荧光" aria-label="Permalink to &quot;科学日报 2026-11-02（物理 · 1/2）：体积散射显微 VSM——不扫描、不测波前，也能在强散射组织里重建三维荧光&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-02.md</code> ｜ DOI: 10.1038/s41467-026-79103-6 ｜ Nature Communications (2026)</p></blockquote><ul><li>问题：生物组织的<strong>光学散射</strong>会破坏空间与角度信息，从根本上<strong>限制荧光成像</strong>，使<strong>组织内三维可视化</strong>成为难题；此前的硬件密集方案或计算方法虽有进展，却受<strong>仪器复杂度与轴向歧义</strong>制约。</li><li>方法：提出<strong>体积散射显微（VSM）</strong>——一个<strong>无扫描的光学—计算框架</strong>：用<strong>孔径分割的傅里叶光场</strong>配置采集<strong>角度分辨的散斑编码荧光</strong>，再通过<strong>自适应特征去散射</strong>与<strong>子孔径联合对齐</strong>重建三维结构。</li><li>结果（实测）： <ul><li>在<strong>不测量波前、不机械扫描</strong>的前提下<strong>保留散射光中嵌入的角度信息</strong>，同时保持<strong>标准落射荧光架构的简洁性</strong>；</li><li>在<strong>仿体、工程化细胞体系、带体积性肌肉缺失的离体组织</strong>以及<strong>完整的非洲爪蟾胚胎</strong>上展示高保真三维重建；</li><li>在<strong>强散射</strong>下仍保持空间分辨率、增强光学切片能力并具<strong>定量准确性</strong>。</li></ul></li><li>洞察（对本库 <code>physics</code> × <code>materials</code>）： <ol><li><strong>「不物理『校正』散射，而是采集它的角度信息再算回来」</strong> —— 判据：当三维成像被散射卡住时，先问<strong>能否把『扫描/测波前』换成『角度分辨采集 + 计算重建』</strong>。</li><li><strong>「保留标准落射架构」＝改进不靠加硬件</strong> —— 组件还是老的，改变的是<strong>采集编码与重建算法</strong>。判据：<strong>当仪器复杂度是瓶颈时，先找『用现有光路 + 换采集/算法』的路子</strong>（同族母题：<strong>改路径优于加力度</strong>）。</li></ol></li></ul><hr><h2 id="科学日报-2026-11-02-物理-·-2-2-floquet-工程把时间反演对称性「编掉」——单层-mos2-出现手性选择性二次谐波" tabindex="-1">科学日报 2026-11-02（物理 · 2/2）：Floquet 工程把时间反演对称性「编掉」——单层 MoS₂ 出现手性选择性二次谐波 <a class="header-anchor" href="#科学日报-2026-11-02-物理-·-2-2-floquet-工程把时间反演对称性「编掉」——单层-mos2-出现手性选择性二次谐波" aria-label="Permalink to &quot;科学日报 2026-11-02（物理 · 2/2）：Floquet 工程把时间反演对称性「编掉」——单层 MoS₂ 出现手性选择性二次谐波&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-02.md</code> ｜ DOI: 10.1126/sciadv.aed6149 ｜ Science Advances (2026)</p></blockquote><ul><li>问题：对称性破缺深刻影响材料的宏观性质；单层过渡金属硫族化物中<strong>反演对称性破缺</strong>带来<strong>手性选择定则</strong>与独特的光学手性选择性电子性质。问题：<strong>能否用光主动、超快地『编』出新的手性选择非线性响应？</strong></li><li>方法：在<strong>单层二硫化钼（MoS₂）<strong>中，用</strong>亚带隙、圆偏振的超快光脉冲</strong>做 <strong>Floquet 工程</strong>，<strong>打破时间反演对称性</strong>，引入<strong>非简并、手性选择的光学 Stark 位移与 Bloch–Siegert 位移</strong>。</li><li>结果（实测）： <ul><li>位移<strong>有效解除能量简并</strong>，产生<strong>显著的手性选择性二次谐波产生（SHG）</strong>；</li><li>该 Floquet 手性选择态可由<strong>光强、手性</strong>等光学参数<strong>精细调节</strong>。</li></ul></li><li>洞察（对本库 <code>physics</code> × <code>quantum-physics</code>）： <ol><li><strong>「对称性也可以被光『临时』改写」</strong> —— 判据：当你要某材料具备它本来没有的选择定则时，先问<strong>能否用周期驱动（Floquet 工程）在时间维上破缺对称性</strong>，而不是换材料。</li><li><strong>「手性选择性 = 一个可控的光学自由度」</strong> —— 可调的手性 SHG 把「手性」变成<strong>可写入、可调</strong>的量，指向<strong>超快非线性光子学</strong>与<strong>手性光电器件</strong>。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/physics/index.md</code> ｜ <code>topics/quantum-physics/index.md</code> ｜ <code>topics/materials/index.md</code> ｜ 第52期 科学板块</p></blockquote><p>关键词：科学日报第52期、体积散射显微 VSM、无扫描、傅里叶光场、孔径分割、角度分辨散斑、自适应特征去散射、子孔径联合对齐、不测波前、标准落射荧光、爪蟾胚胎、强散射三维成像、定量准确性、Floquet 工程、时间反演对称性破缺、单层 MoS₂、手性选择性二次谐波 SHG、光学 Stark 位移、Bloch-Siegert 位移、亚带隙圆偏振、解除能量简并、超快非线性光子学、改路径优于加力度</p><p>关联：<code>topics/physics/index.md</code>、<code>topics/physics/science-daily-2026-10-31-physics.md</code>、<code>topics/physics/science-daily-2026-10-28-physics.md</code>、<code>topics/quantum-physics/index.md</code>、<code>topics/quantum-physics/science-daily-2026-11-02-quantum.md</code>、<code>topics/materials/index.md</code>、<code>topics/materials/science-daily-2026-10-31-materials.md</code></p>',14)])])}const h=s(n,[["render",r]]);export{u as __pageData,h as default};
